      setTokensInfo({
        token: dataSignIn.token,
        refreshToken: dataSignIn.refreshToken,
        tokenExpires: dataSignIn.tokenExpires,
      });
      setUser(dataSignIn.user);
    }
  });

  return (
    <FormProvider {...methods}>
      <div className="mx-auto w-full max-w-md px-4">
        <form onSubmit={onSubmit}>
          <div className="mb-4 grid grid-cols-12 gap-4">
            <div className="col-span-12 mt-6">
              <h1 className="text-xl font-semibold">{t("sign-up:title")}</h1>
            </div>
            <div className="col-span-12">
              <FormTextInput<SignUpFormData>
                name="firstName"
                label={t("sign-up:inputs.firstName.label")}
                type="text"
                autoFocus
                testId="first-name"
              />
            </div>

            <div className="col-span-12">
              <FormTextInput<SignUpFormData>
                name="lastName"
                label={t("sign-up:inputs.lastName.label")}
                type="text"
                testId="last-name"
              />
            </div>

            <div className="col-span-12">
              <FormTextInput<SignUpFormData>
                name="email"
                label={t("sign-up:inputs.email.label")}
                type="email"
                testId="email"
              />
            </div>

            <div className="col-span-12">
              <FormTextInput<SignUpFormData>
                name="password"
                label={t("sign-up:inputs.password.label")}
                type="password"
                testId="password"
              />
            </div>
            <div className="col-span-12">
              <FormCheckboxInput
                name="policy"
                label=""
                testId="privacy"
                options={policyOptions}
                keyValue="id"
                keyExtractor={(option) => option.id.toString()}
                renderOption={(option) => (
                  <span>
                    {option.name}
                    <Link
                      href="/privacy-policy"
                      target="_blank"
                      className="text-primary underline-offset-4 underline"
                    >
                      {t("sign-up:inputs.policy.label")}
                    </Link>
                  </span>
                )}
              />
            </div>

            <div className="col-span-12">
              <FormActions />
              <span className="ms-2">
                <Button asChild variant="secondary" data-testid="login">
                  <Link href="/sign-in">
                    {t("sign-up:actions.accountAlreadyExists")}
                  </Link>
                </Button>
              </span>
            </div>

            {[isGoogleAuthEnabled, isFacebookAuthEnabled].some(Boolean) && (
              <div className="col-span-12">
                <div className="mb-4 flex items-center gap-2">
                  <Separator className="flex-1" />
                  <span className="rounded-full border bg-muted px-2 py-0.5 text-xs text-muted-foreground">
                    {t("sign-up:or")}
                  </span>
                  <Separator className="flex-1" />
                </div>

                <SocialAuth />
              </div>
            )}
          </div>
        </form>
      </div>
    </FormProvider>
  );
}

function SignUp() {
  return <Form />;
}

export default withPageRequiredGuest(SignUp);

